// pubspec.yaml: camera: ^0.10.5+9
import 'package:camera/camera.dart';

class ScanScreen extends StatefulWidget {
  const ScanScreen({super.key});
  @override State<ScanScreen> createState() => _ScanScreenState();
}

class _ScanScreenState extends State<ScanScreen> with WidgetsBindingObserver {
  CameraController? _controller;
  Future<void>? _init;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _init = _bootCamera();
  }

  Future<void> _bootCamera() async {
    final cams = await availableCameras();
    final back = cams.firstWhere((c) => c.lensDirection == CameraLensDirection.back);
    _controller = CameraController(back, ResolutionPreset.high,
      enableAudio: false,
      imageFormatGroup: ImageFormatGroup.yuv420);   // ML Kit likes YUV420
    await _controller!.initialize();
    if (!mounted) return;
    setState(() {});
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    // Camera must be released when app goes background / re-init on resume
    if (_controller == null || !_controller!.value.isInitialized) return;
    if (state == AppLifecycleState.inactive) {
      _controller?.dispose();
      _controller = null;
    } else if (state == AppLifecycleState.resumed) {
      _init = _bootCamera();
    }
  }

  Future<void> _snap() async {
    final file = await _controller!.takePicture();
    if (!mounted) return;
    Navigator.of(context).push(MaterialPageRoute(builder: (_) => PreviewScreen(file)));
  }

  Future<void> _startBarcodeStream(void Function(CameraImage) onFrame) async {
    await _controller!.startImageStream(onFrame);
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder(
      future: _init,
      builder: (_, s) {
        if (s.connectionState != ConnectionState.done || _controller == null) {
          return const Center(child: CircularProgressIndicator());
        }
        return Stack(children: [
          CameraPreview(_controller!),
          Align(alignment: Alignment.bottomCenter,
            child: Padding(padding: const EdgeInsets.all(24),
              child: FloatingActionButton(onPressed: _snap, child: const Icon(Icons.camera)),
            ),
          ),
        ]);
      },
    );
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _controller?.dispose();
    super.dispose();
  }
}
